{"action":"write_file","path":"flatten.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { flatten } = require('./flatten');

test('flattens one level by default', () => {
  assert.deepEqual(flatten([1, [2, 3], 4]), [1, 2, 3, 4]);
});

test('flattens up to specified depth', () => {
  assert.deepEqual(flatten([1, [2, [3, [4]]]], 1), [1, 2, [3, [4]]]);
  assert.deepEqual(flatten([1, [2, [3, [4]]]], 2), [1, 2, 3, [4]]);
  assert.deepEqual(flatten([1, [2, [3, [4]]]], 3), [1, 2, 3, 4]);
});

test('Infinity flattens everything', () => {
  assert.deepEqual(flatten([1, [2, [3, [4]]]], Infinity), [1, 2, 3, 4]);
});

test('depth of 0 returns a shallow copy', () => {
  const arr = [1, [2, [3]]];
  const res = flatten(arr, 0);
  assert.deepEqual(res, arr);
  assert.notEqual(res, arr);
  assert.equal(res[1], arr[1]);
});

test('validates items is an array', () => {
  assert.throws(() => flatten(null), TypeError);
  assert.throws(() => flatten({}), TypeError);
  assert.throws(() => flatten('123'), TypeError);
});

test('validates depth', () => {
  assert.throws(() => flatten([1], -1), RangeError);
  assert.throws(() => flatten([1], 1.5), RangeError);
  assert.throws(() => flatten([1], NaN), RangeError);
  assert.throws(() => flatten([1], '1'), RangeError);
});

test('handles non-array elements, null, undefined and array-like objects', () => {
  const arrayLike = { 0: 'a', 1: 'b', length: 2 };
  assert.deepEqual(flatten([1, null, undefined, arrayLike, [2]], 1), [1, null, undefined, arrayLike, 2]);
});
"}
